"A notification shows how far they are, with Pause all and Cancel, and the downloads go on when you leave the app or the screen goes off.": "Eine Benachrichtigung zeigt den Fortschritt mit „Alle pausieren“ und „Abbrechen“; die Downloads laufen weiter, wenn du die App verlässt oder der Bildschirm ausgeht.",
"A patch bundle asked the patcher for something this build of the app does not have, so it was made for a different Morphe version. Update the source in Sources; if it still happens, report it with the log.": "Ein Patch-Bundle hat vom Patcher etwas verlangt, das diese App-Version nicht hat, daher wurde es für eine andere Morphe-Version erstellt. Aktualisiere die Quelle unter „Quellen“; tritt es weiter auf, melde es mit dem Protokoll.",
"A patch could not be applied. This usually means the patch does not fit this version of the app. Check the details below and the log.": "Ein Patch konnte nicht angewendet werden. Meist passt der Patch nicht zu dieser App-Version. Sieh dir die Details unten und das Protokoll an.",
"A patch source decides what ends up inside your patched apps. Only add sources you trust. It is downloaded now and listed under Sources.": "Eine Patch-Quelle bestimmt, was in deinen gepatchten Apps landet. Füge nur Quellen hinzu, denen du vertraust. Sie wird jetzt heruntergeladen und unter „Quellen“ aufgelistet.",
"A path exclusion keeps one file or folder, and everything inside it, out of the tools you pick.": "Ein Pfadausschluss hält eine Datei oder einen Ordner samt Inhalt aus den gewählten Werkzeugen heraus.",
"A persistent Shizuku shell: cd and exports stick. Type exit or tap Exit Rish to leave.": "Eine dauerhafte Shizuku-Shell: cd und exportierte Variablen bleiben erhalten. Geben Sie exit ein oder tippen Sie auf „Rish beenden“, um sie zu verlassen.",
