"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Das Ändern von Design und Overlays läuft über die Shell. Verbinden Sie unter „Betriebsmodi“ einen davon und kehren Sie dann zurück.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Das Ändern von Design und Overlays läuft über die Shell. Verbinden Sie unter „Betriebsmodi“ einen davon und kehren Sie dann zurück. Die aktuell verwendeten Farben werden auch ohne Verbindung angezeigt.",
"Changing this can break setup, apps or the system. Only change it if you know what it does.": "Eine Änderung kann Einrichtung, Apps oder System beschädigen. Ändern Sie dies nur, wenn Sie wissen, was es bewirkt.",
