"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Wählen Sie die Anmeldemethode im Verbindungsfenster des Agenten. Tools ohne Android-Build werden in eine Debian-Umgebung innerhalb von Termux installiert. Das dauert mehrere Minuten und braucht bis zu etwa 1 GB; die Anbieter unterstützen Android nicht offiziell, daher läuft ein Tool womöglich nicht auf jedem Telefon.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Legen Sie fest, was die zusätzliche Schaltfläche in jeder Zeile der App-Liste tut. Sie ist immer ein Symbol; die Schaltflächen, die sich nach der App richten (Aktivieren / Deaktivieren, Installieren / Deinstallieren, Fortsetzen / Pausieren), wechseln Symbol und Aktion passend zum aktuellen Zustand der App.",
"Choose what to install and which starter files to write": "Wähle, was installiert und welche Startdateien geschrieben werden sollen",
"Choosing a folder needs the app build": "Das Wählen eines Ordners braucht die App-Version",
"Choosing files works in the app": "Die Dateiauswahl funktioniert in der App",
"Chosen:": "Gewählt:",
"Classic three-button navigation bar": "Klassische Drei-Tasten-Navigationsleiste",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro oder Max und eine Anmeldung mit einem Google-Konto dürfen nur in den eigenen Apps der Anbieter verwendet werden: Anthropic und Google erlauben anderen Apps nicht, diese Anmeldungen zu nutzen. Deshalb meldet das Terminal Sie über die offiziellen Befehlszeilentools an, die in Termux laufen und dort die Website-Anmeldung des Anbieters öffnen:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "Räume auf, was nicht mehr gebraucht wird: überflüssige Dateien, verzichtbare App-Daten, Überreste gelöschter Apps und doppelt vorhandene Dateien. Erst scannen, die Liste ansehen, herausnehmen, was du behalten willst, dann löschen. Die vier Werkzeuge nutzen den Betriebsmodus dieser App für die Ordner, die eine normale App nicht lesen kann.",
"Clean — no engine flagged this file": "Sauber – keine Engine hat diese Datei markiert",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "Die Bereinigung wird simuliert. Dateien werden gescannt und gemeldet, aber nichts wird tatsächlich gelöscht.",
