"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind ist ein MCP-Server: ein Tool, das KI-Agenten über ADB die Kontrolle über ein Android-Gerät gibt (Apps, Dateien, Logs, Screenshots). Für sich allein ist es kein Chat.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind ist in Debian installiert. Starten Sie es mit: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Fügen Sie es Ihrem Agenten als MCP-Server hinzu (seine Adresse wird beim Start ausgegeben).",
