"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "Jede App im F-Droid-Katalog oder in einem der bekannten Drittanbieter-Repositories. Wählen Sie ein Repository, stöbern Sie nach Kategorie und installieren Sie direkt – Downloads werden anhand der veröffentlichten SHA-256-Prüfsumme des Repositorys geprüft.",
