"Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse and Deepseek connect with an API key from the provider's website (links below). Usage is billed by the provider to that key's account; Google's Gemini API also has a free tier, where Google may use what you send to improve its products.": "Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse und Deepseek verbinden sich mit einem API-Schlüssel von der Website des Anbieters (Links unten). Die Nutzung wird vom Anbieter dem Konto dieses Schlüssels in Rechnung gestellt; die Gemini API von Google hat auch eine kostenlose Stufe, bei der Google das, was Sie senden, zur Verbesserung seiner Produkte verwenden kann.",
