"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Schlüssel werden mit einem Schlüssel verschlüsselt, der in der sicheren Hardware des Telefons bleibt, und nur an die Adresse ihres eigenen Anbieters gesendet. Die Seite sieht sie nach der Eingabe nie wieder; nur die letzten vier Zeichen werden angezeigt.",
