"Not found on USB. Check the cable, unlock the device and make sure USB debugging is on, then try again.": "Nicht per USB gefunden. Prüfe das Kabel, entsperre das Gerät und stelle sicher, dass USB-Debugging an ist, und versuche es dann erneut.",
"Not found on this phone. Enter the address of the computer that runs it, then Connect.": "Auf diesem Telefon nicht gefunden. Geben Sie die Adresse des Computers ein, auf dem es läuft, und tippen Sie dann auf „Verbinden“.",
"Not found: the model may not exist or may not be open to this key. Pick another model.": "Nicht gefunden: Das Modell existiert möglicherweise nicht oder ist für diesen Schlüssel nicht freigegeben. Wählen Sie ein anderes Modell.",
