"Patched apps are signed with a key that is made on this phone the first time. Keep using the same key to update a patched app in place.": "Gepatchte Apps werden mit einem Schlüssel signiert, der beim ersten Mal auf diesem Telefon erstellt wird. Nutze weiter denselben Schlüssel, um eine gepatchte App an Ort und Stelle zu aktualisieren.",
