"Patches from different sources are built independently and can conflict. Sticking to one source per app is the safe default. Continue?": "Patches aus verschiedenen Quellen werden unabhängig gebaut und können sich widersprechen. Pro App bei einer Quelle zu bleiben, ist die sichere Voreinstellung. Fortfahren?",
