"Perplexity": "Perplexity",
"Phone makers and apps add settings of their own.": "Telefonhersteller und Apps fügen eigene Einstellungen hinzu.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "Wähle ein .mpp-Patch-Bundle aus dem Speicher. Eine lokale Quelle aktualisiert sich nie selbst: Wähle die neue Datei, wenn eine erscheint.",
"Pick a Coding Agent in the Terminal first": "Wählen Sie zuerst im Terminal einen Coding-Agenten aus",
"Pick a package file to read it and choose how to install it.": "Wählen Sie eine Paketdatei, um sie zu lesen und die Installationsart festzulegen.",
"Pick a package first": "Wählen Sie zuerst ein Paket",
"Pick an agent under Coding Agents to chat": "Wählen Sie unter „Coding-Agenten“ einen Agenten, um zu chatten",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Wählen Sie einen Agenten, dann das Modell und den Aufwand (Niedrig, Ausgewogen oder Hoch: wie intensiv er nachdenken soll). Beim ersten Mal beginnen beide mit einer ausgewogenen Wahl, und der Agent fragt nach dem, was er braucht (einen API-Schlüssel, eine Serveradresse oder eine Anmeldung), und testet es, bevor Sie loslegen.",
"Pick at least one agent": "Wählen Sie mindestens einen Agenten aus",
"Pick at least one patch": "Wähle mindestens einen Patch",
