"Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Sag kurz: was sie steuert, was ihre Werte bedeuten, was eine Änderung bewirkt und ob sie sich gefahrlos ändern lässt. Sag klar, wenn du die Einstellung nicht kennst (viele gehören dem Telefonhersteller), statt zu raten, und sag dann, was ihr Name nahelegt. Kurze Absätze, keine Überschriften.",
