"Termux could not be opened. Is it installed?": "Termux konnte nicht geöffnet werden. Ist es installiert?",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termux nimmt noch keine Befehle von anderen Apps an. Führen Sie in Termux aus:",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termux nimmt noch keine Befehle von anderen Apps an: Führen Sie den Befehl aus Schritt 3 in Termux aus und testen Sie dann erneut.",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termux ist kostenlos. Laden Sie es von F-Droid oder GitHub herunter; der alte Build aus Google Play ist nicht geeignet.",
"Termux is not installed. It is free from F-Droid or GitHub.": "Termux ist nicht installiert. Es ist kostenlos bei F-Droid oder GitHub erhältlich.",
"Termux is not set up for this app yet.": "Termux ist für diese App noch nicht eingerichtet.",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux ist bereit: vim, nano, git und python sind installiert und bash hat seine Start-.bashrc. Öffne das echte Terminal für Vollbild-Programme.",
"Termux permission": "Termux-Berechtigung",
