"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Termux-Shells lesen zuerst ~/.bash_profile oder ~/.profile (PATH und Ähnliches). Schalten Sie dies aus, wenn Ihr Profil ein anderes Programm startet.",
