"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "Dem Patcher ging der Speicher aus. Schließe andere Apps und versuche es erneut, oder schalte in den Patcher-Einstellungen „Nicht benötigte native Bibliotheken entfernen“ ein.",
