"The patches could not be read": "Die Patches konnten nicht gelesen werden",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Die Patches unterstützen diese App-Version nicht. Hole mit Morphe Helper eine unterstützte Version oder schalte in den Patcher-Einstellungen „Nicht unterstützte Versionen patchen“ ein.",
"The paths could not be read.": "Die Pfade konnten nicht gelesen werden.",
