"The project gives no description for this package.": "Das Projekt enthält keine Beschreibung für dieses Paket.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Die Anbieter unterstützen Android nicht offiziell: Das Tool läuft womöglich nicht auf jedem Telefon. Wenn etwas fehlschlägt, zeigt das Terminal die genauen Meldungen des Tools.",
