"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "Der Bildschirm zeigt kurz nacheinander die Einstellungen einer App nach der anderen, während für jede App, die noch einen für Dateien unerreichbaren Cache hat, „Cache leeren“ angetippt wird. Eine Abdeckung zeigt, was passiert, mit einer Schaltfläche „Abbrechen“. Es hört auf, wenn der Bildschirm ausgeht.",
