"The service is off.": "Der Dienst ist aus.",
"The service is switched on but has not connected yet; turn it off and on again in the accessibility settings.": "Der Dienst ist eingeschaltet, aber noch nicht verbunden; schalte ihn in den Bedienungshilfen-Einstellungen aus und wieder an.",
"The setting's name, table and current value are sent to them.": "Name, Tabelle und aktueller Wert der Einstellung werden an sie gesendet.",
