"The sources that are on do not have patches yet, or the patch engine could not read them. Open Sources to update them.": "Die eingeschalteten Quellen haben noch keine Patches, oder die Patch-Engine konnte sie nicht lesen. Öffne „Quellen“, um sie zu aktualisieren.",
"The sources, Fast mode and VirusTotal flow of Morphe Helper follow": "Quellen, Schnellmodus und VirusTotal-Ablauf von Morphe Helper folgen",
