"Theme style": "Designstil",
"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Erteilen Sie dieser App dann die Berechtigung „Run commands in Termux environment“ und testen Sie die Verbindung. Die Termux-Einrichtung in den Terminal-Einstellungen führt Sie durch die Schritte.",
"There are no saved lists to back up yet": "Es gibt noch keine gespeicherten Listen zum Sichern",
"There are no saved lists to back up yet; Restore works anyway.": "Es gibt noch keine gespeicherten Listen zum Sichern; Wiederherstellen funktioniert trotzdem.",
"There are no saved lists to share yet": "Es gibt noch keine gespeicherten Listen zum Teilen",
"There are no usable lists in that file.": "In dieser Datei gibt es keine verwendbaren Listen.",
"There is no key yet": "Es gibt noch keinen Schlüssel",
"There is no undo.": "Dies lässt sich nicht rückgängig machen.",
"There is nothing to delete. Scan first.": "Es gibt nichts zu löschen. Scanne zuerst.",
"These apps are currently selected for this action:": "Diese Apps sind derzeit für diese Aktion ausgewählt:",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Diese Apps sind deinstalliert, aber ihre Datenordner sind noch auf dem Telefon. Die Daten der angehakten Apps werden endgültig gelöscht.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Diese Apps sind deinstalliert. Ohne Root kann die App nicht sehen, welche davon noch Daten haben; alle zu leeren ist daher sicher, findet aber bei manchen vielleicht nichts. Die Daten der angehakten Apps werden endgültig gelöscht.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Die Releases dieser Apps liegen auf Websites, die diese App nicht direkt prüfen kann. Obtainium kann sie verfolgen.",
"These files are too different to compare line by line. View each one instead.": "Diese Dateien unterscheiden sich zu stark für einen zeilenweisen Vergleich. Sehen Sie sich stattdessen jede einzeln an.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Sie laufen weiter, wenn der Browser geschlossen wird. „Pausieren“ behält, was heruntergeladen wurde, und „Fortsetzen“ fragt die Seite nur nach dem Rest (eine Seite, die das nicht kann, beginnt die Datei von vorn).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Sie werden übersprungen, es sei denn, du patchst trotzdem, was scheitern oder die App beschädigen kann.",
"Third-party packages only": "Nur Pakete von Drittanbietern",
"This App's ADB Key": "ADB-Schlüssel dieser App",
"This Shizuku version is too old. Please update Shizuku.": "Diese Shizuku-Version ist zu alt. Bitte aktualisieren Sie Shizuku.",
"This action cannot be undone.": "Diese Aktion kann nicht rückgängig gemacht werden.",
