"To browse files on this phone, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Zum Durchsuchen von Dateien auf diesem Telefon benötigt diese App den Zugriff auf alle Dateien (oder einen Betriebsmodus: ADB, Shizuku oder Root).",
"To get an explanation, choose a default agent and connect it.": "Wähle für eine Erklärung einen Standard-Agenten und verbinde ihn.",
"To look in Downloads this app needs": "Um in Downloads zu suchen, braucht diese App",
"To make this the default installer, open any APK, choose this app, and tap \"Always\".": "Um dies zum Standard-Installer zu machen, öffnen Sie ein beliebiges APK, wählen diese App und tippen auf „Immer“.",
"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Zum Durchsuchen des Speichers nach APK-, APKS-, APKM- und XAPK-Dateien benötigt diese App den Zugriff auf alle Dateien (oder einen Betriebsmodus: ADB, Shizuku oder Root).",
"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Für die Suche nach Schriftarten im Speicher braucht diese App den Zugriff auf alle Dateien. Sie können auch eine Schriftdatei von Hand auswählen, wofür kein Zugriff nötig ist.",
"To search storage, this app needs": "Zum Durchsuchen des Speichers benötigt diese App",
"To search the files on this phone, this app needs All-files access.": "Um die Dateien auf diesem Telefon zu durchsuchen, braucht die App Zugriff auf alle Dateien.",
"To use DroidMind with an agent that speaks MCP (such as Claude Code or OpenCode), install it into the Debian container in Termux. Then start it with droidmind --transport sse and add it to that agent as an MCP server.": "Um DroidMind mit einem Agenten zu nutzen, der MCP spricht (etwa Claude Code oder OpenCode), installieren Sie es im Debian-Container in Termux. Starten Sie es dann mit droidmind --transport sse und fügen Sie es diesem Agenten als MCP-Server hinzu.",
